L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "\233\155\133\231\180\128\230\167\152\227\130\146\229\183\187\227\129\141\232\190\188\227\129\191\227\129\159\227\129\143\227\129\170\227\129\139\227\129\163\227\129\159\227\129\174\227\129\167\227\129\153\227\129\140\227\128\129\n\231\181\144\229\177\128\227\129\147\227\129\134\227\129\151\227\129\166\229\138\169\227\129\145\227\129\166\227\129\132\227\129\159\227\129\160\227\129\141\227\129\190\227\129\151\227\129\159\227\128\130"
