L23_1.m_Talk_SCN = "\232\153\189\231\132\182\228\184\141\230\131\179\232\174\169\233\155\133\231\186\170\228\185\159\229\141\183\229\133\165\232\191\153\228\187\182\228\186\139\239\188\140\228\189\134\230\156\128\231\187\136\228\187\150\229\141\180\229\184\174\228\186\134\229\164\167\229\191\153\227\128\130"
